// Shape of each entry in blogs-repo/index.json (generated by scripts/generate-blog-index.js)
export interface BlogPostSummary {
  slug: string;
  file: string;
  title: string;
  description: string;
  date: string;
  tags: string[];
  pinned: boolean;
  author: string;
  readingTime: number;
  numberOfLike?: number;
  background?: string;
  showBackground?: boolean;
  isNotebook?: boolean;
}

export interface BlogPost extends BlogPostSummary {
  content: string;
  notebookData?: unknown;
}
